	//   uninstall_patch:     kb=<KB####>
	//   stage_patch:         kb=<KB####>
	//   software_deploy*:    name=<...>, version=<...>, action=<install|uninstall>
	//   collect_file:        paths=<N>, first=<first path>
	//   file_operation:      op=<copy|move|write_bytes|...>, src=<...>, dst=<...>
